<?php require_once __DIR__.'/includes/auth.php';$page_title='General Settings';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();foreach(['site_name','support_url','retention_days'] as $k){$s=db()->prepare('INSERT INTO settings(setting_key,setting_value,is_public) VALUES(?,?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value),is_public=VALUES(is_public)');$s->execute([$k,trim($_POST[$k]??''),in_array($k,['site_name','support_url'],true)?1:0]);}log_activity('General settings updated',(int)$admin['id']);flash('success','General settings saved.');go('settings.php');}include __DIR__.'/includes/header.php';?><div class="page-title"><div><h1>General Settings</h1><p>Update public values without editing PHP files.</p></div></div><section class="panel"><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><div class="field"><label>SITE NAME</label><input class="input" name="site_name" value="<?=e((string)setting('site_name','ERAN+'))?>"></div><div class="field"><label>PUBLIC SUPPORT URL</label><input class="input" name="support_url" value="<?=e((string)setting('support_url','#'))?>"></div><div class="field"><label>UPLOAD RETENTION DAYS</label><input class="input" type="number" name="retention_days" value="<?=e((string)setting('retention_days',30))?>"></div><button class="button button-primary">SAVE GENERAL SETTINGS</button></form></section><?php include __DIR__.'/includes/footer.php';?>
